    },
    {
      "card_ids": ["C29"],
      "claim": "Valbenazine, a more metabolically stabilized tetrabenazine-related prodrug, has an absolute oral bioavailability of about 49%, but the query lacks the protective ester prodrug motif and is more tetrabenazine-like.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a tetrabenazine-like dimethoxy-substituted fused lactam/amine. Direct tetrabenazine data show very low oral bioavailability (0.1–8.5%), well below the 20% threshold. More bioavailable analogs are structurally distant or prodrug-stabilized, so the prediction is low.",
  "evidence_gaps": [
    "No direct human or animal oral bioavailability data exist for the exact query molecule.",
